<?php
declare(strict_types=1);
require_once __DIR__.'/../config/auth.php';
page_require(['ALUMNO']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi cuenta — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{max-width:760px;margin:auto;padding:22px 14px 40px}.hero{background:#123b5d;color:#fff;border-radius:20px;padding:22px;margin-bottom:14px}.hero h1{margin:0 0 4px;font-size:28px}.hero .sub{opacity:.8;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.card{background:#fff;border-radius:16px;padding:16px;box-shadow:0 4px 16px #0000000d}.wide{grid-column:1/-1}.label{font-size:10px;text-transform:uppercase;color:#64748b;font-weight:900;letter-spacing:.05em}.value{font-size:18px;font-weight:850;margin-top:4px}.small{font-size:12px;color:#64748b;margin-top:5px}.row{padding:10px 0;border-top:1px solid #eef2f7}.row:first-child{border-top:0}.money{font-weight:800}.badge{display:inline-block;padding:4px 7px;border-radius:999px;background:#e2e8f0;font-size:10px;font-weight:900}.actions{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}button,a.action{border:0;border-radius:9px;padding:10px 12px;font-weight:800;cursor:pointer;text-decoration:none}.primary{background:#1976a8;color:#fff}.ghost{background:#e8eef2;color:#334155}input,textarea{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:9px;font-size:15px}label{display:block;margin:10px 0 5px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase}.msg{margin-top:8px;font-size:12px;color:#166534;font-weight:700}.logout{margin-top:14px;width:100%;background:#172033;color:#fff}.notice{background:#eef6fb;border:1px solid #d8eaf5;border-radius:12px;padding:12px;margin-top:8px}.notice h3{margin:0 0 5px;font-size:15px}.notice p{margin:0;white-space:pre-wrap;font-size:13px;color:#334155}@media(max-width:620px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><main class="wrap"><section class="hero"><h1 id="nombre">Mi cuenta</h1><div class="sub">Hache Natación</div></section><div class="grid"><section class="card"><div class="label">Plan</div><div class="value" id="plan">—</div><div class="small" id="planMeta"></div></section><section class="card"><div class="label">Horario</div><div class="value" id="horario">—</div><div class="small" id="estado"></div></section><section class="card wide"><h2>Avisos de Hache</h2><div id="mensajes">Cargando…</div></section><section class="card wide"><h2>Mis datos</h2><label>WhatsApp</label><input id="whatsapp"><label>Correo</label><input id="correo" type="email"><div class="actions"><button class="primary" id="guardarPerfil">Guardar datos</button><a class="action ghost" href="/cambiar-password.php">Cambiar contraseña</a></div><div id="perfilMsg" class="msg"></div></section><section class="card wide"><h2>Avisar ausencia</h2><label>Desde</label><input type="date" id="desde"><label>Hasta</label><input type="date" id="hasta"><label>Motivo</label><textarea id="motivo" rows="3" placeholder="Ej. Viaje fuera de la ciudad"></textarea><div class="actions"><button class="primary" id="avisar">Enviar aviso</button></div><div id="msg" class="msg"></div></section><section class="card wide"><h2>Mis avisos</h2><div id="avisos">Cargando…</div></section><section class="card wide"><h2>Pagos recientes</h2><div id="pagos">Cargando…</div></section><section class="card wide"><h2>Reposiciones</h2><div id="repos">Cargando…</div></section><section class="card wide"><h2>Cursos intensivos</h2><div id="intensivos">Cargando…</div></section></div><button id="logout" class="logout">Cerrar sesión</button></main><script>
const f=d=>d?String(d).slice(0,10):'—';const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(body){const r=await fetch('/api/portal-alumno.php',body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}
async function cargar(){try{const d=await api(),a=d.alumno;nombre.textContent=a.nombre;plan.textContent=a.plan_nombre||'Sin plan';planMeta.textContent=a.plan_nombre?`${a.sesiones_semana} sesiones/semana · ${money(a.precio)}`:'';horario.textContent=a.hora_inicio&&a.hora_fin?`${a.hora_inicio.slice(0,5)}–${a.hora_fin.slice(0,5)}`:'Sin horario';estado.textContent=a.estado_administrativo;whatsapp.value=a.whatsapp||'';correo.value=a.correo||'';mensajes.innerHTML=d.mensajes.map(x=>`<div class="notice"><h3>${esc(x.titulo)}</h3><p>${esc(x.cuerpo)}</p><div class="small">${f(x.created_at)}</div></div>`).join('')||'<div class="small">Sin avisos nuevos.</div>';avisos.innerHTML=d.avisos.map(x=>`<div class="row"><b>${f(x.fecha_desde)}${x.fecha_hasta!==x.fecha_desde?' → '+f(x.fecha_hasta):''}</b> <span class="badge">${esc(x.estado)}</span><div class="small">${esc(x.motivo)}</div>${x.estado==='ACTIVO'?`<button class="ghost" data-cancel="${x.id}" style="margin-top:6px">Cancelar aviso</button>`:''}</div>`).join('')||'<div class="small">Sin avisos.</div>';pagos.innerHTML=d.pagos.map(x=>`<div class="row"><span class="money">${money(x.importe)}</span> · ${esc(x.tipo)}<div class="small">${f(x.fecha)} · ${esc(x.metodo)} · ${esc(x.estado)}</div></div>`).join('')||'<div class="small">Sin pagos.</div>';repos.innerHTML=d.reposiciones.map(x=>`<div class="row"><b>${esc(x.estado)}</b><div class="small">Ausencia: ${f(x.fecha_ausencia)}</div></div>`).join('')||'<div class="small">Sin reposiciones.</div>';intensivos.innerHTML=d.intensivos.map(x=>`<div class="row"><b>${f(x.fecha_inicio)} → ${f(x.fecha_fin)}</b> <span class="badge">${esc(x.estado)}</span><div class="small">${x.hora_inicio?x.hora_inicio.slice(0,5)+'–'+x.hora_fin.slice(0,5):''} · Reposiciones: ${Number(x.reposiciones_justificadas||0)+Number(x.reposiciones_cancelacion||0)}</div></div>`).join('')||'<div class="small">Sin cursos intensivos.</div>'}catch(e){document.body.innerHTML='<main class="wrap"><div class="card">'+esc(e.message)+'</div></main>'}}
const today=new Date().toISOString().slice(0,10);desde.value=today;hasta.value=today;desde.onchange=()=>{if(!hasta.value||hasta.value<desde.value)hasta.value=desde.value};avisar.onclick=async()=>{msg.textContent='';try{await api({accion:'AVISO',fecha_desde:desde.value,fecha_hasta:hasta.value,motivo:motivo.value.trim()});msg.textContent='Aviso registrado.';motivo.value='';await cargar()}catch(e){msg.textContent=e.message}};guardarPerfil.onclick=async()=>{perfilMsg.textContent='';try{await api({accion:'PERFIL',whatsapp:whatsapp.value.trim(),correo:correo.value.trim()});perfilMsg.textContent='Datos actualizados.'}catch(e){perfilMsg.textContent=e.message}};avisos.onclick=async e=>{const b=e.target.closest('[data-cancel]');if(!b)return;if(confirm('¿Cancelar este aviso?')){try{await api({accion:'CANCELAR_AVISO',id:b.dataset.cancel});await cargar()}catch(err){alert(err.message)}}};logout.onclick=async()=>{await fetch('/api/sesion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accion:'LOGOUT'})});sessionStorage.removeItem('hache_usuario');location.href='/'};cargar();
</script></body></html>